window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9e9ce4192bc5cd4a"]={"versions": [{"id": "FIG-9e9ce4192bc5cd4a", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR ECU Resource Templates. Das Metamodell definiert die strukturelle Modellierung von speicherabgebildeten Hardwareschnittstellen (Memory Mapped HW Ports) sowie deren Verbindungen und Zugriffsparameter innerhalb der Hardware-Ressourcenbeschreibung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Modellelemente, Attribute und Assoziationen:</p>\n<ul class=\"fig-list\"><li><strong>HWPort</strong> («Identifiable»): Basisklasse für Hardware-Ports mit dem Attribut <code>direction: Enumeration{in, out, inout}</code>. Steht in einer 1-zu-(2..*)-Assoziation (<code>+hwPort</code>) zu <code>AssemblyHWConnection</code>.\n</li><li><strong>MemoryMappedHWPort</strong>: Spezialisierung von <code>HWPort</code>. Verfügt über die Attribute <code>dataInterfaceWidth: Int</code> und <code>hwPortType: Enumeration{unspecified, data, control}</code>.\n</li><li><strong>ProvidedMemorySegment</strong> («HWElement»): Über eine gerichtete gestrichelte Beziehung (<code>memoryHWPorts</code>) an <code>MemoryMappedHWPort</code> angebunden.\n</li><li><strong>AssemblyHWConnection</strong> («HWConnection»): Basisklasse für Verbindungsstrukturen zwischen Hardware-Ports.\n</li><li><strong>MemoryMappedAssemblyHWConnection</strong>: Spezialisierung von <code>AssemblyHWConnection</code>. Definiert Attribute zur Konfiguration: <code>baseAddress: Int [0..1]</code>, <code>segmentUsage: Enumeration{code, data, stack, boot} [0..*]</code>, <code>byteOrder: Enumeration{LittleEndian, BigEndian} [0..1]</code> und <code>cachable: Boolean [0..1]</code>. Enthält per Komposition (<code>+hwConnectionAccess</code>, Multiplizität 0..*) Instanzen von <code>MemoryAccess</code>.\n</li><li><strong>MemoryAccess</strong>: Beschreibt den Zugriffstyp über das Attribut <code>accessType: Enumeration{read, write, erase, programm, random, sequence, burst}</code>. Enthält per Komposition (<code>+time</code>, Multiplizität 0..1) das Timing-Element <code>TimeRange</code>.\n</li><li><strong>TimeRange</strong>: Spezifiziert Zeitbereiche mit den Attributen <code>min: Float [0..1]</code>, <code>max: Float</code> und <code>typical: Float [0..1]</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Dynamische Zugriffszeiten und Ausprägungen von Speicheroperationen werden deklarativ über die Entitäten <code>MemoryAccess</code> und <code>TimeRange</code> parametrisiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Modellierer und Tool-Entwickler verbindet <code>MemoryMappedAssemblyHWConnection</code> mindestens zwei <code>HWPort</code>-Instanzen (<code>2..*</code>), die als <code>MemoryMappedHWPort</code> ausgeprägt sein können. Optionale Konfigurationsparameter (<code>baseAddress</code>, <code>byteOrder</code>, <code>cachable</code>) müssen bei Nicht-Angabe über Plattform-Defaults oder Adress-Mappings aufgelöst werden. <code>TimeRange</code> erfordert zwingend das Attribut <code>max: Float</code>, während <code>min</code> und <code>typical</code> optional sind.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c3dae528cab4aaf5", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR ECU Resource Templates. Das Metamodell definiert die strukturelle Modellierung von speicherabgebildeten Hardwareschnittstellen (Memory Mapped HW Ports) sowie deren Verbindungen und Zugriffsparameter innerhalb der Hardware-Ressourcenbeschreibung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Modellelemente, Attribute und Assoziationen:</p>\n<ul class=\"fig-list\"><li><strong>HWPort</strong> («Identifiable»): Basisklasse für Hardware-Ports mit dem Attribut <code>direction: Enumeration{in, out, inout}</code>. Steht in einer 1-zu-(2..*)-Assoziation (<code>+hwPort</code>) zu <code>AssemblyHWConnection</code>.\n</li><li><strong>MemoryMappedHWPort</strong>: Spezialisierung von <code>HWPort</code>. Verfügt über die Attribute <code>dataInterfaceWidth: Int</code> und <code>hwPortType: Enumeration{unspecified, data, control}</code>.\n</li><li><strong>ProvidedMemorySegment</strong> («HWElement»): Über eine gerichtete gestrichelte Beziehung (<code>memoryHWPorts</code>) an <code>MemoryMappedHWPort</code> angebunden.\n</li><li><strong>AssemblyHWConnection</strong> («HWConnection»): Basisklasse für Verbindungsstrukturen zwischen Hardware-Ports.\n</li><li><strong>MemoryMappedAssemblyHWConnection</strong>: Spezialisierung von <code>AssemblyHWConnection</code>. Definiert Attribute zur Konfiguration: <code>baseAddress: Int [0..1]</code>, <code>segmentUsage: Enumeration{code, data, stack, boot} [0..*]</code>, <code>byteOrder: Enumeration{LittleEndian, BigEndian} [0..1]</code> und <code>cachable: Boolean [0..1]</code>. Enthält per Komposition (<code>+hwConnectionAccess</code>, Multiplizität 0..*) Instanzen von <code>MemoryAccess</code>.\n</li><li><strong>MemoryAccess</strong>: Beschreibt den Zugriffstyp über das Attribut <code>accessType: Enumeration{read, write, erase, programm, random, sequence, burst}</code>. Enthält per Komposition (<code>+time</code>, Multiplizität 0..1) das Timing-Element <code>TimeRange</code>.\n</li><li><strong>TimeRange</strong>: Spezifiziert Zeitbereiche mit den Attributen <code>min: Float [0..1]</code>, <code>max: Float</code> und <code>typical: Float [0..1]</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Dynamische Zugriffszeiten und Ausprägungen von Speicheroperationen werden deklarativ über die Entitäten <code>MemoryAccess</code> und <code>TimeRange</code> parametrisiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Modellierer und Tool-Entwickler verbindet <code>MemoryMappedAssemblyHWConnection</code> mindestens zwei <code>HWPort</code>-Instanzen (<code>2..*</code>), die als <code>MemoryMappedHWPort</code> ausgeprägt sein können. Optionale Konfigurationsparameter (<code>baseAddress</code>, <code>byteOrder</code>, <code>cachable</code>) müssen bei Nicht-Angabe über Plattform-Defaults oder Adress-Mappings aufgelöst werden. <code>TimeRange</code> erfordert zwingend das Attribut <code>max: Float</code>, während <code>min</code> und <code>typical</code> optional sind.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-717f445370f74fcd", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR ECU Resource Templates. Das Metamodell definiert die strukturelle Modellierung von speicherabgebildeten Hardwareschnittstellen (Memory Mapped HW Ports) sowie deren Verbindungen und Zugriffsparameter innerhalb der Hardware-Ressourcenbeschreibung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Modellelemente, Attribute und Assoziationen:</p>\n<ul class=\"fig-list\"><li><strong>HWPort</strong> («Identifiable»): Basisklasse für Hardware-Ports mit dem Attribut <code>direction: Enumeration{in, out, inout}</code>. Steht in einer 1-zu-(2..*)-Assoziation (<code>+hwPort</code>) zu <code>AssemblyHWConnection</code>.\n</li><li><strong>MemoryMappedHWPort</strong>: Spezialisierung von <code>HWPort</code>. Verfügt über die Attribute <code>dataInterfaceWidth: Int</code> und <code>hwPortType: Enumeration{unspecified, data, control}</code>.\n</li><li><strong>ProvidedMemorySegment</strong> («HWElement»): Über eine gerichtete gestrichelte Beziehung (<code>memoryHWPorts</code>) an <code>MemoryMappedHWPort</code> angebunden.\n</li><li><strong>AssemblyHWConnection</strong> («HWConnection»): Basisklasse für Verbindungsstrukturen zwischen Hardware-Ports.\n</li><li><strong>MemoryMappedAssemblyHWConnection</strong>: Spezialisierung von <code>AssemblyHWConnection</code>. Definiert Attribute zur Konfiguration: <code>baseAddress: Int [0..1]</code>, <code>segmentUsage: Enumeration{code, data, stack, boot} [0..*]</code>, <code>byteOrder: Enumeration{LittleEndian, BigEndian} [0..1]</code> und <code>cachable: Boolean [0..1]</code>. Enthält per Komposition (<code>+hwConnectionAccess</code>, Multiplizität 0..*) Instanzen von <code>MemoryAccess</code>.\n</li><li><strong>MemoryAccess</strong>: Beschreibt den Zugriffstyp über das Attribut <code>accessType: Enumeration{read, write, erase, programm, random, sequence, burst}</code>. Enthält per Komposition (<code>+time</code>, Multiplizität 0..1) das Timing-Element <code>TimeRange</code>.\n</li><li><strong>TimeRange</strong>: Spezifiziert Zeitbereiche mit den Attributen <code>min: Float [0..1]</code>, <code>max: Float</code> und <code>typical: Float [0..1]</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Dynamische Zugriffszeiten und Ausprägungen von Speicheroperationen werden deklarativ über die Entitäten <code>MemoryAccess</code> und <code>TimeRange</code> parametrisiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Modellierer und Tool-Entwickler verbindet <code>MemoryMappedAssemblyHWConnection</code> mindestens zwei <code>HWPort</code>-Instanzen (<code>2..*</code>), die als <code>MemoryMappedHWPort</code> ausgeprägt sein können. Optionale Konfigurationsparameter (<code>baseAddress</code>, <code>byteOrder</code>, <code>cachable</code>) müssen bei Nicht-Angabe über Plattform-Defaults oder Adress-Mappings aufgelöst werden. <code>TimeRange</code> erfordert zwingend das Attribut <code>max: Float</code>, während <code>min</code> und <code>typical</code> optional sind.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-9e9ce4192bc5cd4a", "to": "FIG-c3dae528cab4aaf5", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>TimeRange: Der untere Bildrand schneidet die Attributliste von TimeRange vertikal ab, sodass <code>min: Float [0..1]</code>, <code>max: Float</code> und <code>typical: Float [0..1]</code> unvollständig sichtbar sind.\n</li></ul>"}, {"from": "FIG-c3dae528cab4aaf5", "to": "FIG-717f445370f74fcd", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
